<script>
(()=>{const boxes=[...document.querySelectorAll('[data-compare]')],count=document.getElementById('compare-count'),open=document.getElementById('compare-open'),dialog=document.getElementById('compare-dialog');const refresh=()=>{const selected=boxes.filter(box=>box.checked);if(selected.length>2){selected[selected.length-1].checked=false;return refresh()}count.textContent=selected.length;open.disabled=selected.length!==2};boxes.forEach(box=>box.addEventListener('change',refresh));open.addEventListener('click',()=>{const cards=boxes.filter(box=>box.checked).map(box=>box.closest('[data-product-card]')),table=dialog.querySelector('table'),head=table.querySelector('thead tr');head.replaceChildren(Object.assign(document.createElement('th'),{textContent:'Caractéristique'}));cards.forEach(card=>{const th=document.createElement('th');th.textContent=card.dataset.name;head.append(th)});const rows=[['Catégorie','category'],['Origine','origin'],['Exploitation','farm'],['Référence','reference'],['Quantité disponible','quantity'],['Certifications valides','certifications'],['Indicateur CO₂','co2']],body=table.querySelector('tbody');body.replaceChildren();rows.forEach(([label,key])=>{const tr=document.createElement('tr'),title=document.createElement('th');title.textContent=label;tr.append(title);cards.forEach(card=>{const td=document.createElement('td');td.textContent=card.dataset[key]||'—';tr.append(td)});body.append(tr)});dialog.showModal()});document.querySelector('[data-close-compare]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})})();
</script>
